use actix_web::{web, App, HttpResponse, HttpServer, Responder, post};
use serde::Deserialize;
use std::fs::File;
use std::io::Read;
use std::path::PathBuf;

#[derive(Deserialize)]
struct SongRequest {
    filename: String,
}

#[post("/download")]
async fn download_song(req: web::Json<SongRequest>) -> impl Responder {
    let base_path = PathBuf::from("/var/songs");
    let file_path = base_path.join(&req.filename);

    if !file_path.exists() {
        return HttpResponse::NotFound().body("File does not exist");
    }

    let mut file = match File::open(&file_path) {
        Ok(file) => file,
        Err(_) => return HttpResponse::NotFound().body("File does not exist"),
    };

    let mut buffer = Vec::new();
    if let Err(_) = file.read_to_end(&mut buffer) {
        return HttpResponse::InternalServerError().body("Failed to read file");
    }

    HttpResponse::Ok()
        .content_type("audio/mpeg")
        .body(buffer)
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .service(download_song)
    })
    .bind("0.0.0.0:5000")?
    .run()
    .await
}
```
