use std::path::Path;

fn is_safe_path(base: &Path, input: &str) -> bool {
    let full_path = base.join(input);
    if let Ok(canonical) = full_path.canonicalize() {
        return canonical.starts_with(base);
    }
    false
}

fn main() {
    let base_path = Path::new("/var/songs");
    let input = "../../etc/passwd";
    assert!(!is_safe_path(base_path, input), "Path traversal detected!");
}

